// BudgetBuddy dropdown/modal reproduction harness (ISC-213, ISC-220..222).
// Runs headless Chrome against the isolated dev instance on :8899.
import puppeteer from "puppeteer";

const BASE = "http://127.0.0.1:8899";
const results = {};

async function signIn(page) {
  await page.goto(`${BASE}/`, { waitUntil: "networkidle0" });
  if (page.url().includes("/signin")) {
    await page.waitForSelector('input[type="password"]');
    await page.type('input[type="password"]', "1234");
    await page.click('button[type="submit"]');
    await page.waitForNavigation({ waitUntil: "networkidle0" }).catch(() => {});
  }
}

async function openAddBudget(page) {
  // Master page "Add budget" button.
  await page.waitForFunction(
    () => [...document.querySelectorAll("button")].some((b) => b.textContent.trim() === "Add budget"),
    { timeout: 15000 },
  );
  await page.evaluate(() => {
    [...document.querySelectorAll("button")].find((b) => b.textContent.trim() === "Add budget").click();
  });
  await page.waitForSelector('[role="dialog"]', { timeout: 5000 });
}

const dialogOpen = (page) => page.evaluate(() => Boolean(document.querySelector('[role="dialog"]')));
const listboxOpen = (page) => page.evaluate(() => Boolean(document.querySelector('[role="listbox"]')));

// Click a combobox trigger INSIDE the dialog by index using real mouse coords —
// synthetic .click() bypasses the pointer-events state we're testing.
async function mouseClickCombobox(page, idx) {
  const box = await page.evaluate((i) => {
    const dlg = document.querySelector('[role="dialog"]');
    const el = dlg.querySelectorAll('[role="combobox"]')[i];
    const r = el.getBoundingClientRect();
    return { x: r.x + r.width / 2, y: r.y + r.height / 2 };
  }, idx);
  await page.mouse.click(box.x, box.y);
  await new Promise((r) => setTimeout(r, 400));
}

const browser = await puppeteer.launch({ headless: "new", args: ["--no-sandbox"] });
try {
  // ---- Probe 1 (ISC-213/214): trigger re-click must not close the dialog ----
  const page = await browser.newPage();
  await page.setViewport({ width: 1280, height: 800 });
  page.on("console", (m) => {
    if (m.text().includes("[dialog-guard]")) console.log("CONSOLE:", m.text());
  });
  await signIn(page);
  await openAddBudget(page);
  await mouseClickCombobox(page, 1); // Period select — open
  const openedDropdown = await listboxOpen(page);
  await mouseClickCombobox(page, 1); // Period select — close by re-click
  const dropdownAfter = await listboxOpen(page);
  const dialogAfter = await dialogOpen(page);
  results.probe1 = { openedDropdown, dropdownAfter, dialogAfter };

  // ---- Probe 2 (ISC-216): overlay click with nothing open still closes ----
  if (!dialogAfter) {
    await openAddBudget(page);
  }
  await page.mouse.click(8, 8); // top-left corner = overlay
  await new Promise((r) => setTimeout(r, 400));
  results.probe2 = { dialogClosedByOverlay: !(await dialogOpen(page)) };

  // ---- Probe 3 (ISC-220..222): mobile scroll ----
  const m = await browser.newPage();
  await m.setViewport({ width: 375, height: 667, isMobile: true, hasTouch: true });
  await signIn(m);
  await openAddBudget(m);
  results.probe3 = await m.evaluate(() => {
    const dlg = document.querySelector('[role="dialog"]');
    const r = dlg.getBoundingClientRect();
    const buttons = [...dlg.querySelectorAll("button")];
    const submit = buttons[buttons.length - 1].getBoundingClientRect();
    return {
      dialogTop: r.top,
      dialogBottom: r.bottom,
      viewportH: window.innerHeight,
      scrollable: dlg.scrollHeight > dlg.clientHeight + 1,
      overflowY: getComputedStyle(dlg).overflowY,
      submitBottom: submit.bottom,
      submitReachableWithoutScroll: submit.bottom <= window.innerHeight && submit.top >= 0,
    };
  });

  // Desktop no-scrollbar check (ISC-222)
  results.probe4 = await page.evaluate(() => {
    const dlg = document.querySelector('[role="dialog"]');
    if (!dlg) return { note: "dialog not open (reopen skipped)" };
    return { desktopScrollable: dlg.scrollHeight > dlg.clientHeight + 1 };
  });
} finally {
  console.log("RESULTS:", JSON.stringify(results, null, 2));
  await browser.close();
}

// Bug A deep probe: touch taps + element-at-point diagnostics.
import puppeteer from "puppeteer";

const BASE = "http://127.0.0.1:8899";

async function signIn(page) {
  await page.goto(`${BASE}/`, { waitUntil: "networkidle0" });
  if (page.url().includes("/signin")) {
    await page.waitForSelector('input[type="password"]');
    await page.type('input[type="password"]', "1234");
    await page.click('button[type="submit"]');
    await page.waitForNavigation({ waitUntil: "networkidle0" }).catch(() => {});
  }
}

async function openAddBudget(page) {
  await page.waitForFunction(
    () => [...document.querySelectorAll("button")].some((b) => b.textContent.trim() === "Add budget"),
    { timeout: 15000 },
  );
  await page.evaluate(() => {
    [...document.querySelectorAll("button")].find((b) => b.textContent.trim() === "Add budget").click();
  });
  await page.waitForSelector('[role="dialog"]', { timeout: 5000 });
}

async function comboBox(page, idx) {
  return page.evaluate((i) => {
    const dlg = document.querySelector('[role="dialog"]');
    const el = dlg?.querySelectorAll('[role="combobox"]')[i];
    if (!el) return null;
    const r = el.getBoundingClientRect();
    return { x: r.x + r.width / 2, y: r.y + r.height / 2 };
  }, idx);
}

const atPoint = (page, x, y) =>
  page.evaluate(
    (px, py) => {
      const el = document.elementFromPoint(px, py);
      return el
        ? { tag: el.tagName, role: el.getAttribute("role"), cls: (el.className || "").toString().slice(0, 60), bodyPE: getComputedStyle(document.body).pointerEvents }
        : { tag: null, bodyPE: getComputedStyle(document.body).pointerEvents };
    },
    x,
    y,
  );

const state = (page) =>
  page.evaluate(() => ({
    dialog: Boolean(document.querySelector('[role="dialog"]')),
    listbox: Boolean(document.querySelector('[role="listbox"]')),
  }));

const browser = await puppeteer.launch({ headless: "new", args: ["--no-sandbox"] });
const out = {};
try {
  // ---- Touch tap sequence on mobile viewport ----
  const m = await browser.newPage();
  await m.setViewport({ width: 375, height: 667, isMobile: true, hasTouch: true });
  await signIn(m);
  await openAddBudget(m);
  // Period combobox (index 1 when creating an expense)
  let c = await comboBox(m, 1);
  await m.touchscreen.tap(c.x, c.y);
  await new Promise((r) => setTimeout(r, 500));
  out.afterFirstTap = await state(m);
  // Where is the trigger point now? (is the popper covering it?)
  out.elementAtTriggerWhileOpen = await atPoint(m, c.x, c.y);
  await m.touchscreen.tap(c.x, c.y);
  await new Promise((r) => setTimeout(r, 500));
  out.afterSecondTap = await state(m);

  // ---- Same with the Parent/category dropdown (index 0, longer list) ----
  const m2 = await browser.newPage();
  await m2.setViewport({ width: 375, height: 667, isMobile: true, hasTouch: true });
  await signIn(m2);
  await openAddBudget(m2);
  c = await comboBox(m2, 0);
  await m2.touchscreen.tap(c.x, c.y);
  await new Promise((r) => setTimeout(r, 500));
  out.parent_afterFirstTap = await state(m2);
  out.parent_elementAtTrigger = await atPoint(m2, c.x, c.y);
  await m2.touchscreen.tap(c.x, c.y);
  await new Promise((r) => setTimeout(r, 500));
  out.parent_afterSecondTap = await state(m2);

  // ---- Desktop, but check element under cursor when open ----
  const d = await browser.newPage();
  await d.setViewport({ width: 1280, height: 800 });
  await signIn(d);
  await openAddBudget(d);
  c = await comboBox(d, 1);
  await d.mouse.click(c.x, c.y);
  await new Promise((r) => setTimeout(r, 400));
  out.desktop_open = await state(d);
  out.desktop_elementAtTrigger = await atPoint(d, c.x, c.y);
} finally {
  console.log("RESULTS:", JSON.stringify(out, null, 2));
  await browser.close();
}

import * as React from "react";
import * as SelectPrimitive from "@radix-ui/react-select";
import { Check, ChevronDown, Search } from "lucide-react";
import { cn } from "@/lib/utils";

const Select = SelectPrimitive.Root;
const SelectGroup = SelectPrimitive.Group;
const SelectValue = SelectPrimitive.Value;

// --- Nested-layer tracking (see DialogContent's onInteractOutside) -----------
//
// While a Select is open the page is pointer-events-suspended, so the tap that
// closes the dropdown lands on the dialog OVERLAY. With a mouse the dialog's
// dismissable layer is suppressed at pointerdown time, but on TOUCH the
// gesture's trailing `click` arrives after the Select's layer has unmounted,
// and the dialog treats it as a bare overlay tap and closes too (the
// close-a-dropdown-closes-the-modal bug). The dialog therefore vetoes any
// outside interaction whose gesture STARTED while a select layer was open —
// latched at pointerdown-capture, which runs before every Radix handler.
let openSelectLayers = 0;
let selectLayerOpenAtLastPointerDown = false;
if (typeof document !== "undefined") {
  document.addEventListener(
    "pointerdown",
    () => {
      selectLayerOpenAtLastPointerDown = openSelectLayers > 0;
    },
    { capture: true },
  );
}
export function selectLayerOwnsCurrentGesture(): boolean {
  return openSelectLayers > 0 || selectLayerOpenAtLastPointerDown;
}

function useSelectLayerTracking(): void {
  React.useEffect(() => {
    openSelectLayers += 1;
    return () => {
      openSelectLayers -= 1;
    };
  }, []);
}

const SelectTrigger = React.forwardRef<
  React.ElementRef<typeof SelectPrimitive.Trigger>,
  React.ComponentPropsWithoutRef<typeof SelectPrimitive.Trigger>
>(({ className, children, ...props }, ref) => (
  <SelectPrimitive.Trigger
    ref={ref}
    className={cn(
      "flex h-10 w-full items-center justify-between rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background focus:outline-none focus:ring-2 focus:ring-ring disabled:cursor-not-allowed disabled:opacity-50",
      className
    )}
    {...props}
  >
    {children}
    <SelectPrimitive.Icon asChild>
      <ChevronDown className="h-4 w-4 opacity-50" />
    </SelectPrimitive.Icon>
  </SelectPrimitive.Trigger>
));
SelectTrigger.displayName = SelectPrimitive.Trigger.displayName;

const SelectContent = React.forwardRef<
  React.ElementRef<typeof SelectPrimitive.Content>,
  React.ComponentPropsWithoutRef<typeof SelectPrimitive.Content>
>(({ className, children, position = "popper", ...props }, ref) => {
  useSelectLayerTracking();
  return (
    <SelectPrimitive.Portal>
      <SelectPrimitive.Content
        ref={ref}
        className={cn(
          // Cap to the popper's measured available height so a small viewport
          // (or an open on-screen keyboard) never clips options off-screen.
          "relative z-50 max-h-[min(24rem,var(--radix-select-content-available-height))] min-w-[8rem] overflow-hidden rounded-md border bg-popover text-popover-foreground shadow-md",
          position === "popper" && "data-[side=bottom]:translate-y-1",
          className
        )}
        position={position}
        {...props}
      >
        <SelectPrimitive.Viewport className={cn("p-1", position === "popper" && "w-full min-w-[var(--radix-select-trigger-width)]")}>
          {children}
        </SelectPrimitive.Viewport>
      </SelectPrimitive.Content>
    </SelectPrimitive.Portal>
  );
});
SelectContent.displayName = SelectPrimitive.Content.displayName;

const SelectItem = React.forwardRef<
  React.ElementRef<typeof SelectPrimitive.Item>,
  React.ComponentPropsWithoutRef<typeof SelectPrimitive.Item>
>(({ className, children, ...props }, ref) => (
  <SelectPrimitive.Item
    ref={ref}
    className={cn(
      "relative flex w-full cursor-pointer select-none items-center rounded-sm py-1.5 pl-8 pr-2 text-sm outline-none focus:bg-accent focus:text-accent-foreground data-[disabled]:pointer-events-none data-[disabled]:opacity-50",
      className
    )}
    {...props}
  >
    <span className="absolute left-2 flex h-3.5 w-3.5 items-center justify-center">
      <SelectPrimitive.ItemIndicator>
        <Check className="h-4 w-4" />
      </SelectPrimitive.ItemIndicator>
    </span>
    <SelectPrimitive.ItemText>{children}</SelectPrimitive.ItemText>
  </SelectPrimitive.Item>
));
SelectItem.displayName = SelectPrimitive.Item.displayName;

// --- Searchable, alphabetically sorted select content ------------------------

export interface SearchableSelectOption {
  readonly value: string;
  /** Plain-text label — drives search matching and alphabetical sorting. */
  readonly label: string;
  /** Optional richer display (amounts, suffixes); defaults to the label. */
  readonly render?: React.ReactNode;
  /** Sentinels: "top" pins above the sorted list, "bottom" below it. */
  readonly pin?: "top" | "bottom";
  /** Options sort alphabetically WITHIN their group; group blocks keep their
   *  first-appearance order (e.g. categories block, then incomes block). */
  readonly group?: string;
  readonly disabled?: boolean;
}

interface SearchableSelectContentProps
  extends React.ComponentPropsWithoutRef<typeof SelectPrimitive.Content> {
  options: readonly SearchableSelectOption[];
  /** Alphabetical (locale-aware) sorting of non-pinned options. Default true. */
  sort?: boolean;
  /** The search box appears when the list has at least this many options. */
  searchThreshold?: number;
  searchPlaceholder?: string;
}

const labelCompare = (a: SearchableSelectOption, b: SearchableSelectOption) =>
  a.label.localeCompare(b.label, undefined, { sensitivity: "base", numeric: true });

/**
 * Drop-in SelectContent for dynamic entity lists (categories, envelopes,
 * accounts): options arrive as data, render alphabetically sorted with pinned
 * sentinels, and a search box filters the list once it is long enough to need
 * one. Keystrokes stay contained to the search input (Radix typeahead would
 * otherwise hijack them); ArrowDown hands focus to the list; Enter picks the
 * first visible option; Escape still closes the dropdown. The input autofocuses
 * on fine-pointer devices only, so phones never get a surprise keyboard.
 */
const SearchableSelectContent = React.forwardRef<
  React.ElementRef<typeof SelectPrimitive.Content>,
  SearchableSelectContentProps
>(({ options, sort = true, searchThreshold = 6, searchPlaceholder = "Search…", className, position = "popper", ...props }, ref) => {
  useSelectLayerTracking();
  const [query, setQuery] = React.useState("");
  const inputRef = React.useRef<HTMLInputElement>(null);
  const listRef = React.useRef<HTMLDivElement>(null);
  const showSearch = options.length >= searchThreshold;

  const visible = React.useMemo(() => {
    const q = query.trim().toLowerCase();
    const matches = (o: SearchableSelectOption) => !q || o.label.toLowerCase().includes(q);
    const tops = options.filter((o) => o.pin === "top" && matches(o));
    const bottoms = options.filter((o) => o.pin === "bottom" && matches(o));
    let mids = options.filter((o) => !o.pin && matches(o));
    if (sort) {
      const groupOrder = [...new Set(options.filter((o) => !o.pin).map((o) => o.group ?? ""))];
      mids = groupOrder.flatMap((g) => mids.filter((o) => (o.group ?? "") === g).sort(labelCompare));
    }
    return [...tops, ...mids, ...bottoms];
  }, [options, query, sort]);

  // Autofocus the search box on fine pointers only — on touch the on-screen
  // keyboard would cover the options the user came to tap.
  React.useEffect(() => {
    if (!showSearch || window.matchMedia("(pointer: coarse)").matches) return;
    const t = setTimeout(() => inputRef.current?.focus(), 10);
    return () => clearTimeout(t);
  }, [showSearch]);

  const focusOption = (last: boolean) => {
    const items = listRef.current?.querySelectorAll<HTMLElement>('[role="option"]:not([data-disabled])');
    if (items && items.length > 0) items[last ? items.length - 1 : 0].focus();
  };

  const onSearchKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "Escape") return; // Radix closes the dropdown
    if (e.key === "ArrowDown" || e.key === "ArrowUp") {
      e.preventDefault();
      e.stopPropagation();
      focusOption(e.key === "ArrowUp");
      return;
    }
    if (e.key === "Enter") {
      e.preventDefault();
      e.stopPropagation();
      const first = listRef.current?.querySelector<HTMLElement>('[role="option"]:not([data-disabled])');
      if (first) {
        first.focus();
        first.dispatchEvent(new KeyboardEvent("keydown", { key: "Enter", bubbles: true, cancelable: true }));
      }
      return;
    }
    // Everything else is typing — keep it away from Radix's typeahead.
    e.stopPropagation();
  };

  return (
    <SelectPrimitive.Portal>
      <SelectPrimitive.Content
        ref={ref}
        className={cn(
          "relative z-50 flex max-h-[min(24rem,var(--radix-select-content-available-height))] min-w-[8rem] flex-col overflow-hidden rounded-md border bg-popover text-popover-foreground shadow-md",
          position === "popper" && "data-[side=bottom]:translate-y-1",
          className
        )}
        position={position}
        {...props}
      >
        {showSearch && (
          <div className="flex shrink-0 items-center gap-2 border-b px-3 py-2" onKeyDown={onSearchKeyDown}>
            <Search className="h-4 w-4 shrink-0 opacity-50" />
            <input
              ref={inputRef}
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              placeholder={searchPlaceholder}
              aria-label="Search options"
              // 16px on phones so iOS does not zoom the page on focus.
              className="w-full bg-transparent text-base outline-none placeholder:text-muted-foreground sm:text-sm"
            />
          </div>
        )}
        <SelectPrimitive.Viewport
          ref={listRef}
          className={cn("flex-1 overflow-y-auto p-1", position === "popper" && "w-full min-w-[var(--radix-select-trigger-width)]")}
        >
          {visible.length === 0 && <div className="py-6 text-center text-sm text-muted-foreground">No matches</div>}
          {visible.map((o) => (
            <SelectItem key={o.value} value={o.value} disabled={o.disabled}>
              {o.render ?? o.label}
            </SelectItem>
          ))}
        </SelectPrimitive.Viewport>
      </SelectPrimitive.Content>
    </SelectPrimitive.Portal>
  );
});
SearchableSelectContent.displayName = "SearchableSelectContent";

export { Select, SelectGroup, SelectValue, SelectTrigger, SelectContent, SelectItem, SearchableSelectContent };

