      )}
      onInteractOutside={(e) => {
        // The gesture that closes an open dropdown lands on this dialog's
        // overlay (page pointer-events are suspended while a Select is open);
        // on touch its trailing click would ALSO dismiss the dialog. Veto any
        // outside interaction belonging to a gesture a select layer owns.
        if (selectLayerOwnsCurrentGesture()) {
