/**
 * Radix Select root with a touch-reliable outside-close. Radix defers its
 * outside-press dismissal to the gesture's trailing click, which never fires
 * the layer's dismiss on touch (the tap lands on the parent dialog's overlay —
 * see selectLayerOwnsCurrentGesture below), so tapping the trigger of an OPEN
 * dropdown on a phone previously closed nothing (or, before the dialog guard,
 * closed the whole modal). This wrapper closes the dropdown itself the moment
 * a press starts outside the popover; presses inside it stay Radix's business.
 */
const Select = ({ open: openProp, defaultOpen, onOpenChange, ...rest }: React.ComponentProps<typeof SelectPrimitive.Root>) => {
  const [uncontrolledOpen, setUncontrolledOpen] = React.useState(defaultOpen ?? false);
  const isControlled = openProp !== undefined;
  const open = isControlled ? openProp : uncontrolledOpen;

  const setOpen = React.useCallback(
    (o: boolean) => {
      if (!isControlled) setUncontrolledOpen(o);
      onOpenChange?.(o);
    },
    [isControlled, onOpenChange],
  );

  React.useEffect(() => {
    if (!open) return;
    const onPointerDown = (e: PointerEvent) => {
      const t = e.target as Element | null;
      // The popper wrapper encloses the whole dropdown (list, search box).
      if (t?.closest('[data-radix-popper-content-wrapper], [role="listbox"]')) return;
      setOpen(false);
    };
    document.addEventListener("pointerdown", onPointerDown, { capture: true });
    return () => document.removeEventListener("pointerdown", onPointerDown, { capture: true });
  }, [open, setOpen]);

  return <SelectPrimitive.Root {...rest} open={open} onOpenChange={setOpen} />;
};
const SelectGroup = SelectPrimitive.Group;

