const onPointerDown = (e: PointerEvent) => {
  const t = e.target as Element | null;
  // The popper wrapper encloses the whole dropdown (list, search box).
  if (t?.closest('[data-radix-popper-content-wrapper], [role="listbox"]')) return;
  setOpen(false);
  // Closing restores the page's pointer events mid-gesture, so the same
  // gesture's trailing click would land on whatever the close reveals —
  // usually the trigger, silently REOPENING the dropdown. One gesture
  // closes one layer: swallow that click.
  const swallow = (ce: MouseEvent) => {
    ce.stopPropagation();
    ce.preventDefault();
  };
  document.addEventListener("click", swallow, { capture: true, once: true });
  setTimeout(() => document.removeEventListener("click", swallow, { capture: true }), 600);
};

