interface SelectRootContextValue {
  /** The currently selected value (kept mounted by SearchableSelectContent). */
  readonly value: string | undefined;
  /** Programmatic selection: commit a value and close the dropdown. */
  readonly select: (value: string) => void;
}
const SelectRootContext = React.createContext<SelectRootContextValue>({ value: undefined, select: () => {} });

const Select = ({ open: openProp, defaultOpen, onOpenChange, ...rest }: React.ComponentProps<typeof SelectPrimitive.Root>) => {
  const [uncontrolledOpen, setUncontrolledOpen] = React.useState(defaultOpen ?? false);
  const isControlled = openProp !== undefined;
  const open = isControlled ? openProp : uncontrolledOpen;

  const setOpen = React.useCallback(
    (o: boolean) => {
      if (!isControlled) setUncontrolledOpen(o);
      onOpenChange?.(o);
    },
    [isControlled, onOpenChange],
  );

  const { value, onValueChange } = rest;
  const rootContext = React.useMemo<SelectRootContextValue>(
    () => ({
      value,
      select: (v: string) => {
        onValueChange?.(v);
        setOpen(false);
      },
    }),
    [value, onValueChange, setOpen],
  );

  return (
    <SelectRootContext.Provider value={rootContext}>
      <SelectPrimitive.Root {...rest} open={open} onOpenChange={setOpen} />
    </SelectRootContext.Provider>
  );
};

