// READ-ONLY gap-origin audit: which flows moved cash without an envelope?
import { Database } from "bun:sqlite";
const db = new Database("/home/nicholas-wood/.penny/penny.db", { readonly: true });

interface Row { txn_date: string; amount_cents: number; account_id: string; category_id: string | null; is_transfer: number; payee: string }
const txns = db.query(`
  SELECT txn_date, amount_cents, account_id, category_id, is_transfer, payee
  FROM transactions WHERE is_pending = 0 AND txn_date >= '2026-06-01' ORDER BY txn_date
`).all() as Row[];

interface Mapping { category_id: string; envelope_id: string; effective_from: string; effective_to: string | null }
const mappings = db.query("SELECT category_id, envelope_id, effective_from, effective_to FROM mappings").all() as Mapping[];
const catName = new Map((db.query("SELECT id, name FROM categories").all() as any[]).map((c) => [String(c.id), c.name]));

const mappedAt = (cat: string | null, date: string): boolean => {
  if (cat === null) return false;
  return mappings.some((m) => m.category_id === String(cat) && m.effective_from <= date && (m.effective_to === null || m.effective_to >= date));
};

// Per-day flows that move cash but no envelope
const byDay = new Map<string, { transfer: number; unmapped: number; notes: string[] }>();
const day = (d: string) => { if (!byDay.has(d)) byDay.set(d, { transfer: 0, unmapped: 0, notes: [] }); return byDay.get(d)!; };

for (const t of txns) {
  if (t.is_transfer === 1) {
    day(t.txn_date).transfer += t.amount_cents;
    continue;
  }
  if (!mappedAt(t.category_id, t.txn_date)) {
    const d = day(t.txn_date);
    d.unmapped += t.amount_cents;
    if (Math.abs(t.amount_cents) >= 2000)
      d.notes.push(`${(t.amount_cents / 100).toFixed(2)} ${catName.get(String(t.category_id)) ?? t.category_id ?? "NO-CAT"} ${String(t.payee).slice(0, 34)}`);
  }
}

const cents = (n: number) => (n / 100).toFixed(2);
let cumT = 0, cumU = 0;
console.log("date        transferNet  unmappedNet  (cum transfer / cum unmapped)");
for (const [d, v] of [...byDay.entries()].sort()) {
  if (v.transfer === 0 && v.unmapped === 0) continue;
  cumT += v.transfer; cumU += v.unmapped;
  console.log(`${d}  ${cents(v.transfer).padStart(11)}  ${cents(v.unmapped).padStart(11)}   (${cents(cumT)} / ${cents(cumU)})`);
  for (const n of v.notes) console.log(`             · ${n}`);
}
console.log("\nTOTAL cash-moved-without-envelope since 2026-06-01:", cents(cumT + cumU));
console.log("(positive = cash arrived no envelope claims; negative = cash left without an envelope being spent)");
EOF
