function balancesAt(dateIso: string): { cash: number; cardOwed: number } {
  let cash = 0, card = 0;
  for (const a of accounts) {
    const id = String(a.id);
    const cur = a.current_balance ? Math.round(a.current_balance * 100) : 0;
    const after = (db.query(
      "SELECT COALESCE(SUM(amount_cents),0) net FROM transactions WHERE account_id = ?1 AND is_pending = 0 AND txn_date > ?2",
