    let bal = cur - after;
    if (id === "4771153") bal -= pendNet; // strip today's pendings from the card's live balance
    if ((a.type ?? "").toLowerCase().includes("credit")) card += bal;
    else cash += bal;
  }
  return { cash, cardOwed: Math.abs(card) };
}

